def main():
    resources=[]
    for short,title,url,domains,scope,limits in SOURCES:
        resources.append(dict(id='R-LSYS-'+short,title=title,url=url,authors=['Primary project maintainers'],year=2026,edition=title,kind='manual',access='Public primary passages inspected',domains=domains.split(),role='oracle',reason=limits,prerequisites=['Accepted C17 project prerequisites and explicit toolchain boundary'],locators=[scope],assignable=True,inspection=dict(date='2026-10-17',method='Opened and read named primary web/source passages before supplement authorship',scope=scope,limits=limits)))
    write(HERE/'resources.json',dict(schema_version=1,resources=resources))
    write(HERE/'research_gate.json',dict(status='passage-inspected',domains=['T07','T08','T09','T10','T11'],research_input_sha256={(HERE/'resources.json').relative_to(ROOT).as_posix():hashlib.sha256((HERE/'resources.json').read_bytes()).hexdigest()},limitations=['Author inspection only; no independent human review.','Uninspected published ISO C editions, private books and unavailable source passages remain explicit reference gaps.']))
